using System;
using System.Reflection;
using System.Runtime.InteropServices;
using TweakBench.Notify;

// The version attributes are generated by Build.ps1 from src\App\Release.cs (see the build agent's version file).
[assembly: AssemblyTitle("Tweak Bench Notifications")]
[assembly: AssemblyProduct("Tweak Bench")]
[assembly: AssemblyDescription("Keeps Windows notification pop-ups where you put them in Tweak Bench.")]

namespace TweakBench.NotificationsHelper
{
    /// <summary>
    /// Entry point of "Tweak Bench Notifications.exe": a windowless background program (no WPF) started at sign-in by Tweak Bench.
    /// It runs without administrator rights, one copy at a time. "--version" prints its version and exits.
    /// </summary>
    public static class Program
    {
        [DllImport("kernel32.dll")] static extern bool AttachConsole(int processId);
        [DllImport("kernel32.dll")] static extern IntPtr GetStdHandle(int handle);
        [DllImport("kernel32.dll")] static extern bool SetStdHandle(int handle, IntPtr value);
        [DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
        static extern IntPtr CreateFile(string name, uint access, uint share, IntPtr security, uint disposition, uint flags, IntPtr template);

        [STAThread]
        public static int Main(string[] args)
        {
            if (args.Length > 0 && args[0] == "--version")
            {
                WriteOut(NotificationMover.Version);
                return 0;
            }
            return NotificationMover.Run();
        }

        /// <summary>This is a GUI-subsystem exe: --version attaches to the parent terminal's console unless output is already redirected.</summary>
        static void WriteOut(string text)
        {
            try
            {
                IntPtr handle = GetStdHandle(-11);
                if (handle == IntPtr.Zero || handle == new IntPtr(-1))
                {
                    if (AttachConsole(-1))
                    {
                        IntPtr console = CreateFile("CONOUT$", 0x40000000, 2, IntPtr.Zero, 3, 0, IntPtr.Zero);
                        if (console != new IntPtr(-1)) SetStdHandle(-11, console);
                    }
                }
                Console.Out.WriteLine(text);
                Console.Out.Flush();
            }
            catch (Exception) { }
        }
    }
}
